 import * as THREE from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform, sin, fract } from 'three/tsl';

const ATLAS_X = 0;
const ATLAS_Y = 0;
const ATLAS_W = 512;
const ATLAS_H = 320;

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = config.id ?? 'features-card-2';

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- engineered gradient surface panel ---
  const ink = new THREE.Color(colors.ink);
  const surface = new THREE.Color(colors.surface);
  const uInk = uniform(ink);
  const uSurf = uniform(surface);

  const vUv = uv();
  const grain = fract(
    sin(vUv.x.mul(12.9898).add(vUv.y.mul(78.233))).mul(43758.5453)
  ).mul(0.045);
  const grad = mix(uSurf, uInk, smoothstep(0, 1, vUv.y));
  const panelColorNode = grad.add(vec3(grain));

  const aspect = ATLAS_W / ATLAS_H;
  const cardHeight = 1.0;
  const cardWidth = cardHeight * aspect;
  const padding = 0.08;

  const panelGeo = new THREE.PlaneGeometry(cardWidth + padding * 2, cardHeight + padding * 2);
  const panelMat = new THREE.MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  panelMat.colorNode = panelColorNode;

  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.z = -0.005;
  group.add(panel);

  // --- textured atlas sprite ---
  const spriteGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const spriteMat = new THREE.MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    alphaTest: 0.01
  });
  const sprite = new THREE.Mesh(spriteGeo, spriteMat);
  sprite.position.z = 0.005;
  group.add(sprite);

  let texRef = null;
  let disposed = false;

  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    if (disposed) {
      tex.dispose();
      return;
    }
    texRef = tex;
    tex.colorSpace = THREE.SRGBColorSpace ?? 'srgb';
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;

    const tw = tex.image?.width || ATLAS_W;
    const th = tex.image?.height || ATLAS_H;
    tex.repeat.set(ATLAS_W / tw, ATLAS_H / th);
    tex.offset.set(ATLAS_X / tw, 1 - (ATLAS_Y + ATLAS_H) / th);
    tex.updateMatrix();

    spriteMat.map = tex;
    spriteMat.needsUpdate = true;
  }).catch(() => {});

  // --- billboard toward camera ---
  const camPos = new THREE.Vector3();
  const faceCamera = (renderer, scene, camera) => {
    camera.getWorldPosition(camPos);
    group.lookAt(camPos);
  };
  panel.onBeforeRender = faceCamera;
  sprite.onBeforeRender = faceCamera;

  // --- cleanup & handlers ---
  const timelines = [];
  group.userData.handlers = {};
  group.userData.timelines = timelines;
  group.userData.cleanup = () => {
    disposed = true;
    panelMat.dispose();
    spriteMat.dispose();
    panelGeo.dispose();
    spriteGeo.dispose();
    if (texRef) texRef.dispose();
    timelines.forEach((t) => t.kill?.());
    panel.onBeforeRender = null;
    sprite.onBeforeRender = null;
  };

  return group;
}
